const trashedDue = `-- name: TrashedDue :many
SELECT tenant_id::uuid, asset_id::uuid FROM trashed_due_for_purge($1::int)
`

type TrashedDueRow struct {
	TenantID pgtype.UUID `json:"tenant_id"`
	AssetID  pgtype.UUID `json:"asset_id"`
}

func (q *Queries) TrashedDue(ctx context.Context, days int32) ([]TrashedDueRow, error) {
	rows, err := q.db.Query(ctx, trashedDue, days)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TrashedDueRow
	for rows.Next() {
		var i TrashedDueRow
		if err := rows.Scan(&i.TenantID, &i.AssetID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateLibrary = `-- name: UpdateLibrary :one
UPDATE libraries SET
    name = coalesce($1, name),
    description = coalesce($2, description),
    default_playback_policy = coalesce($3, default_playback_policy),
    mp4_downloads = coalesce($4::bool, mp4_downloads),
    allowed_domains = coalesce($5::text[], allowed_domains),
    blocked_domains = coalesce($6::text[], blocked_domains),
    country_mode = coalesce($7::text, country_mode),
    countries = coalesce($8::text[], countries),
    inherits = ARRAY(SELECT g FROM unnest(inherits) g WHERE g <> ALL($9::text[])),
    updated_at = now()
WHERE id = $10 RETURNING id
`

type UpdateLibraryParams struct {
	Name                  pgtype.Text `json:"name"`
	Description           pgtype.Text `json:"description"`
	DefaultPlaybackPolicy pgtype.Text `json:"default_playback_policy"`
	Mp4Downloads          pgtype.Bool `json:"mp4_downloads"`
	AllowedDomains        []string    `json:"allowed_domains"`
	BlockedDomains        []string    `json:"blocked_domains"`
	CountryMode           pgtype.Text `json:"country_mode"`
	Countries             []string    `json:"countries"`
	Drop                  []string    `json:"drop"`
	ID                    pgtype.UUID `json:"id"`
}

// Null leaves a setting as it is.
func (q *Queries) UpdateLibrary(ctx context.Context, arg UpdateLibraryParams) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, updateLibrary,
		arg.Name,
		arg.Description,
		arg.DefaultPlaybackPolicy,
		arg.Mp4Downloads,
		arg.AllowedDomains,
		arg.BlockedDomains,
		arg.CountryMode,
		arg.Countries,
		arg.Drop,
		arg.ID,
	)
	var id pgtype.UUID
	err := row.Scan(&id)
	return id, err
}

